"""Patch the reconstructed Android WorkerSync for V-Brain 18 data-sync hardening.

The base Android project is reconstructed from the historical payload at build time, then the
current overlay is copied on top. Keeping this transformation explicit makes the migration
repeatable while preserving the stable signer/update path.
"""
from pathlib import Path
import sys

path = Path(sys.argv[1] if len(sys.argv) > 1 else "src/luis-home-app/app/src/main/java/com/luis/home/WorkerSync.java")
s = path.read_text()

# HOME tokens authenticate the Cloudflare HOME backend. Never present them as Supabase JWTs.
# Newer overlays can already carry the explicit X-Home-Authorization header. In that case,
# remove only the duplicate helper constant because patch_veqrya_auth_v22.py owns the final
# shared request block and re-inserts one canonical SUPABASE_FUNCTIONS constant.
old = '''            connection.setRequestProperty("Authorization", "Bearer " + token);\n            connection.setRequestProperty("Content-Type", "application/json; charset=utf-8");'''
new = '''            boolean supabaseFunction = url.startsWith("https://skgmgxthymnzubbobqxu.supabase.co/functions/v1/");\n            if (supabaseFunction) connection.setRequestProperty("X-HOME-Authorization", "Bearer " + token);\n            else connection.setRequestProperty("Authorization", "Bearer " + token);\n            connection.setRequestProperty("Content-Type", "application/json; charset=utf-8");'''
already_hardened = 'connection.setRequestProperty("X-Home-Authorization", bearer);'
if old in s:
    s = s.replace(old, new, 1)
elif already_hardened in s:
    s = s.replace('    private static final String SUPABASE_FUNCTIONS = "https://skgmgxthymnzubbobqxu.supabase.co/functions/v1/";\n', '', 1)
else:
    raise SystemExit("WorkerSync auth anchor not found")

# Queue policy: task/learning writes first; collapse repeated text snapshots; telemetry last.
old = '''    int pendingOutboxCount() { return readOutbox().length(); }\n\n    JSONObject syncStatus() {\n        JSONObject out=new JSONObject();\n        try {\n            android.content.SharedPreferences p=context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE);\n            out.put("configured",isConfigured()).put("pending",pendingOutboxCount())\n               .put("lastSyncedAt",p.getLong("lastSyncedAt",0)).put("lastError",p.getString("lastError",""));\n        } catch(Exception ignored) { }\n        return out;\n    }\n\n    void flushOutbox() {\n        if (!isConfigured() || !flushing.compareAndSet(false, true)) return;\n        long deadline=System.currentTimeMillis()+40000;\n        try {\n            JSONArray rows = readOutbox();'''
new = '''    int pendingOutboxCount() { return readOutbox().length(); }\n\n    private int pendingUserOutboxCount() {\n        JSONArray rows=readOutbox(); int n=0;\n        for(int i=0;i<rows.length();i++){\n            JSONObject row=rows.optJSONObject(i); if(row==null)continue;\n            String type=row.optString("type");\n            if("task".equals(type)||"attempt".equals(type)||"private_activity".equals(type))n++;\n        }\n        return n;\n    }\n\n    private int pendingTelemetryCount() {\n        JSONArray rows=readOutbox(); int n=0;\n        for(int i=0;i<rows.length();i++){\n            JSONObject row=rows.optJSONObject(i);if(row==null)continue;\n            String type=row.optString("type");\n            if("activity".equals(type)||"command_ack".equals(type))n++;\n        }\n        return n;\n    }\n\n    private String privateActivityKey(JSONObject row) {\n        JSONObject p=row==null?null:row.optJSONObject("payload");\n        if(p==null || !"private_text_field".equals(p.optString("kind"))) return "";\n        return p.optString("screen")+"|"+p.optString("taskId")+"|"+p.optString("field");\n    }\n\n    /**\n     * Preserve durable user intent while collapsing redundant snapshots. HOME writes are ordered\n     * before telemetry so a noisy background stream can never starve a To-Do completion.\n     */\n    private JSONArray compactAndPrioritizeOutbox() {\n        try {\n            synchronized(outboxLock){\n                JSONArray rows=readOutbox();\n                JSONArray tasks=new JSONArray(), attempts=new JSONArray(), privateOther=new JSONArray();\n                JSONArray telemetry=new JSONArray(), commands=new JSONArray(), unknown=new JSONArray();\n                java.util.LinkedHashMap<String,JSONObject> latestText=new java.util.LinkedHashMap<>();\n                for(int i=0;i<rows.length();i++){\n                    JSONObject row=rows.optJSONObject(i); if(row==null)continue;\n                    String type=row.optString("type");\n                    if("task".equals(type)) tasks.put(row);\n                    else if("attempt".equals(type)) attempts.put(row);\n                    else if("private_activity".equals(type)){\n                        String k=privateActivityKey(row);\n                        if(k.isEmpty()) privateOther.put(row);\n                        else { latestText.remove(k); latestText.put(k,row); }\n                    }\n                    else if("activity".equals(type)) telemetry.put(row);\n                    else if("command_ack".equals(type)) commands.put(row);\n                    else unknown.put(row);\n                }\n                JSONArray result=new JSONArray();\n                for(JSONArray group:new JSONArray[]{tasks,attempts})\n                    for(int i=0;i<group.length();i++){JSONObject r=group.optJSONObject(i);if(r!=null)result.put(r);}\n                for(JSONObject r:latestText.values()) result.put(r);\n                int privateStart=Math.max(0,privateOther.length()-250);\n                for(int i=privateStart;i<privateOther.length();i++){JSONObject r=privateOther.optJSONObject(i);if(r!=null)result.put(r);}\n                int telemetryStart=Math.max(0,telemetry.length()-80);\n                for(int i=telemetryStart;i<telemetry.length();i++){JSONObject r=telemetry.optJSONObject(i);if(r!=null)result.put(r);}\n                int commandStart=Math.max(0,commands.length()-40);\n                for(int i=commandStart;i<commands.length();i++){JSONObject r=commands.optJSONObject(i);if(r!=null)result.put(r);}\n                for(int i=0;i<unknown.length();i++){JSONObject r=unknown.optJSONObject(i);if(r!=null)result.put(r);}\n                writeOutbox(result);\n                return result;\n            }\n        } catch(Exception ignored) { return readOutbox(); }\n    }\n\n    JSONObject syncStatus() {\n        JSONObject out=new JSONObject();\n        try {\n            android.content.SharedPreferences p=context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE);\n            int user=pendingUserOutboxCount(), telemetry=pendingTelemetryCount();\n            out.put("configured",isConfigured()).put("pending",user).put("pendingUser",user)\n               .put("pendingTelemetry",telemetry).put("pendingTotal",user+telemetry)\n               .put("lastSyncedAt",p.getLong("lastSyncedAt",0)).put("lastError",p.getString("lastError",""));\n        } catch(Exception ignored) { }\n        return out;\n    }\n\n    void flushOutbox() {\n        if (!isConfigured() || !flushing.compareAndSet(false, true)) return;\n        long deadline=System.currentTimeMillis()+40000;\n        try {\n            JSONArray rows = compactAndPrioritizeOutbox();'''
if old not in s:
    raise SystemExit("WorkerSync outbox anchor not found")
s = s.replace(old, new, 1)

# HOME is the durable source of truth. A secondary Supabase mirror must never cause a successful
# HOME write to stay queued and replay indefinitely.
old = '''    private JSONObject sendAttemptNow(JSONObject attempt) throws Exception {\n        JSONObject saved = requestObject("POST", "/api/attempts", new JSONObject(attempt.toString()));\n        mirrorLearningAttempt(attempt);\n        return saved;\n    }'''
new = '''    private JSONObject sendAttemptNow(JSONObject attempt) throws Exception {\n        JSONObject saved = requestObject("POST", "/api/attempts", new JSONObject(attempt.toString()));\n        try { mirrorLearningAttempt(attempt); }\n        catch (Exception mirrorError) {\n            context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE).edit()\n                .putString("lastMirrorError", mirrorError.getMessage()==null?"Learning mirror waiting":mirrorError.getMessage()).apply();\n        }\n        return saved;\n    }'''
if old not in s:
    raise SystemExit("WorkerSync attempt mirror anchor not found")
s = s.replace(old,new,1)

old = '''    private JSONObject sendPrivateActivityNow(JSONObject activity) throws Exception {\n        JSONObject copy = new JSONObject(activity.toString());\n        JSONObject saved = requestObject("POST", "/api/activity", copy);\n        JSONArray activityRows = new JSONArray().put(new JSONObject(copy.toString()));\n        JSONObject body = new JSONObject().put("activity", activityRows);\n        requestAbsolute("POST", LEARNING_INGEST, body, 20000);\n        return saved;\n    }'''
new = '''    private JSONObject sendPrivateActivityNow(JSONObject activity) throws Exception {\n        JSONObject copy = new JSONObject(activity.toString());\n        JSONObject saved = requestObject("POST", "/api/activity", copy);\n        try {\n            JSONArray activityRows = new JSONArray().put(new JSONObject(copy.toString()));\n            JSONObject body = new JSONObject().put("activity", activityRows);\n            requestAbsolute("POST", LEARNING_INGEST, body, 20000);\n        } catch (Exception mirrorError) {\n            context.getSharedPreferences("vbrain_sync",Context.MODE_PRIVATE).edit()\n                .putString("lastMirrorError", mirrorError.getMessage()==null?"Activity mirror waiting":mirrorError.getMessage()).apply();\n        }\n        return saved;\n    }'''
if old not in s:
    raise SystemExit("WorkerSync activity mirror anchor not found")
s = s.replace(old,new,1)

path.write_text(s)
print(f"Patched {path}: HOME-authoritative sync, compact queue, Supabase mirror best-effort")
